def _digit_run_final(run):
    # Batchim index in Hangul jongseong table: 0 none, 1 ㄱ, 4 ㄴ, 8 ㄹ, 16 ㅁ, 17 ㅂ, 21 ㅇ
    n = int(run)
    if n == 0:
        return 21  # 영 ends in ㅇ
    p = 0
    for ch in reversed(run):
        if ch != '0':
            break
        p += 1
    # p = position (from the right) of the lowest nonzero digit
    if p == 0:
        digit = run[-1]
        return {'0': 21, '1': 8, '2': 0, '3': 16, '4': 0,
                '5': 0, '6': 1, '7': 8, '8': 8, '9': 0}[digit]
    if p % 4 != 0:
        # 십 (ㅂ), 백 (ㄱ), 천 (ㄴ)
        return {1: 17, 2: 1, 3: 4}[p % 4]
    g = p // 4
    # 만 (ㄴ), 억 (ㄱ), 조 (none), 경 (ㅇ)
    return {1: 4, 2: 1, 3: 0, 4: 21}.get(g, 0)


def attach_particle(word: str, particle: str) -> str:
    # Find trailing digit run
    end = len(word)
    start = end
    while start > 0 and '0' <= word[start - 1] <= '9':
        start -= 1
    if start < end:
        idx = _digit_run_final(word[start:end])
    else:
        code = ord(word[-1]) - 0xAC00
        idx = code % 28 if 0 <= code < 11172 else 0

    has_batchim = idx != 0
    is_rieul = idx == 8

    if particle == '으로/로':
        chosen = '으로' if (has_batchim and not is_rieul) else '로'
    else:
        consonant_form, vowel_form = particle.split('/')
        chosen = consonant_form if has_batchim else vowel_form
    return word + chosen
